import {getTripleapilogList} from "@/api/dataSharing/dataLog";
import {getDictList} from "@/api/dict";
import threelogDetail from './components/dataLog/threelogDetail'

export default {
  components: {threelogDetail},
  data() {
    return {
      searchForm: {
        current: 1,
        size: 20
      },

      successList: [{
        "dictKey": 0,
        "dictValue": "成功"
      }, {
        "dictKey": 1,
        "dictValue": "失败"
      }],
      dataList: [],
      tableLoading: false, //表格加载
      tableHeight: undefined,
      total: 0,
      selectionList: [],
      valueList: [],
      tripleTypeList: [],

      showDialog: false,
      itemId: '',
    };
  },
  computed: {
    ids() {
      let ids = [];
      this.selectionList.forEach(ele => {
        ids.push(ele.id);
      });
      return ids.join(",");
    }
  },
  mounted() {
    // 设置页面元素高度
    this.setPageContentHeight()
    this.setTableHeight()
    this.getDictList("threeLogValue");
    this.getDictList("tripleTypeList");
    this.getList();

  },
  methods: {
    changeStatus(row) {
      if (row.success === 0) {
        return "成功"
      } else if (row.success === 1) {
        return "失败"
      }
    },

    getDictList(code) {
      //加载字典
      getDictList(code).then(res => {
        if (code === 'threeLogValue') {
          this.valueList = res.data;
        } else if (code === 'tripleTypeList') {
          this.tripleTypeList = res.data;
        }
      });
    },
    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      this.tableHeight = pageBody[0].offsetHeight - 61 - 47 + 'px'
    },
    handleView(row) {
      this.showDialog = true
      this.itemId = row.id
    },
    handleReset() {
      this.searchForm = {
        current: 1,
        size: 20,
      };
      this.getList()
    },
    getList() {
      this.tableLoading = true
      getTripleapilogList(this.searchForm).then(res => {
        this.dataList = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      })
    },
    handleQuery() {
      this.searchForm.current = 1
      this.getList()
    },
    handleDeleteOne(id) {
      //删除按钮
      let ids = id;
      this.handleDeleteConfirm(ids);
      this.selectionList.filter(item => item != id);
    },
    handleDeleteConfirm(ids) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定删除",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return remove(ids);
        })
        .then(() => {
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.getList()
        });
    },
    selectionChange(list) {
      this.selectionList = list;
    },
  }
};
